const RoomTypeInfo* RoomTypeInfoOf(int type)
{
	if(type < 1 || type >= 25 || !s_Rooms[type].name)
		return 0;
	return &s_Rooms[type];
}

const DetailTypeInfo* DetailTypeInfoOf(int type)
{
	if(type < 1 || type >= 143 || !s_Details[type].name)
		return 0;
	return &s_Details[type];
}

